with lines as (select id, service, log_ts, level, status_code, key, v from app_logs lateral view explode(context) t as key, v) select id, service, log_ts, level, status_code, key, v, lag(status_code, 1) over (partition by key order by status_code, id, key) as prev_status_code, round(status_code / sum(status_code) over (partition by service), 4) as status_code_share, ntile(3) over (partition by level order by status_code desc, id, key) as status_code_bucket from lines
